CREATE OR REPLACE FUNCTION public.gym_can_change(g uuid, area text, action text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.gym_operational(g) AND public.otp_verified() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND gym_id=g AND (role='Owner' OR (role IN ('Admin','Reception','Trainer') AND area=ANY(permissions) AND (area||':'||action)=ANY(permissions)))) $$;
GRANT EXECUTE ON FUNCTION public.gym_can_change(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_gym_action() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a text; k text; g uuid; operation text; BEGIN IF auth.uid() IS NULL THEN RETURN coalesce(NEW,OLD); END IF; k=coalesce(NEW.kind,OLD.kind); g=coalesce(NEW.gym_id,OLD.gym_id); a=CASE k WHEN 'gym' THEN 'Profile' WHEN 'members' THEN 'Members' WHEN 'plans' THEN 'Members' WHEN 'workouts' THEN 'Workout programs' WHEN 'trainers' THEN 'Workout programs' WHEN 'sessions' THEN 'Sessions' WHEN 'attendance' THEN 'Attendance' WHEN 'staffAttendance' THEN 'Attendance' WHEN 'products' THEN 'Products' ELSE 'Finance' END; operation=CASE TG_OP WHEN 'INSERT' THEN 'create' WHEN 'DELETE' THEN 'delete' ELSE 'edit' END; IF TG_OP='UPDATE' AND NEW.data IS NOT DISTINCT FROM OLD.data AND NEW.client_id IS NOT DISTINCT FROM OLD.client_id THEN RETURN NEW; END IF; IF NOT public.gym_can_change(g,a,operation) THEN RAISE EXCEPTION 'You do not have permission to % this gym content',operation; END IF; RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER enforce_gym_action BEFORE INSERT OR UPDATE OR DELETE ON public.gym_records FOR EACH ROW EXECUTE FUNCTION public.guard_gym_action();
DO $$ BEGIN EXECUTE replace(replace(pg_get_functiondef('public.save_gym_records(uuid,jsonb)'::regprocedure),'WHEN ''products'' THEN ''Finance''','WHEN ''products'' THEN ''Products'''),'WHEN ''gym'' THEN ''Settings''','WHEN ''gym'' THEN ''Profile'''); END $$;
ALTER POLICY gym_record_read ON public.gym_records USING (gym_operational(gym_id) AND (gym_access(gym_id,CASE kind WHEN 'members' THEN 'Members' WHEN 'plans' THEN 'Members' WHEN 'sessions' THEN 'Sessions' WHEN 'attendance' THEN 'Attendance' WHEN 'staffAttendance' THEN 'Attendance' WHEN 'workouts' THEN 'Workout programs' WHEN 'trainers' THEN 'Workout programs' WHEN 'gym' THEN 'Profile' WHEN 'products' THEN 'Products' ELSE 'Finance' END) OR client_id=auth.uid()));
ALTER TABLE public.staff_invitations ADD COLUMN IF NOT EXISTS invited_user_id uuid REFERENCES public.profiles(id);
CREATE OR REPLACE FUNCTION public.my_staff_invitations() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(to_jsonb(i)||jsonb_build_object('gym_name',g.name)),'[]'::jsonb) FROM public.staff_invitations i JOIN public.gyms g ON g.id=i.gym_id WHERE public.otp_verified() AND public.gym_operational(g.id) AND (i.invited_user_id=auth.uid() OR (i.invited_user_id IS NULL AND lower(i.email)=lower(auth.jwt()->>'email'))) AND i.status='Pending' AND i.expires_at>now() $$;
GRANT EXECUTE ON FUNCTION public.my_staff_invitations() TO authenticated;
CREATE OR REPLACE FUNCTION public.respond_invitation(invitation_id uuid, accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.staff_invitations; BEGIN SELECT * INTO i FROM public.staff_invitations WHERE id=invitation_id FOR UPDATE; IF NOT public.otp_verified() OR NOT public.gym_operational(i.gym_id) OR i.id IS NULL OR i.status!='Pending' OR i.expires_at<=now() OR (i.invited_user_id IS NOT NULL AND i.invited_user_id!=auth.uid()) OR (i.invited_user_id IS NULL AND lower(i.email)!=lower(auth.jwt()->>'email')) THEN RAISE EXCEPTION 'Invitation unavailable'; END IF; IF accept THEN IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND gym_id=i.gym_id) THEN RAISE EXCEPTION 'A gym role already exists for this account'; END IF; INSERT INTO public.user_roles(user_id,gym_id,role,permissions) VALUES(auth.uid(),i.gym_id,i.role,i.permissions); END IF; UPDATE public.staff_invitations SET status=CASE WHEN accept THEN 'Accepted' ELSE 'Declined' END,accepted_by=auth.uid() WHERE id=i.id; END $$;
ALTER POLICY invitations_read ON public.staff_invitations USING (gym_operational(gym_id) AND (gym_access(gym_id,'Settings') OR invited_user_id=auth.uid() OR (invited_user_id IS NULL AND lower(email)=lower(auth.jwt()->>'email'))));
COMMENT ON COLUMN public.user_roles.permissions IS 'Page names grant read access; page:create, page:edit and page:delete grant separate actions. Owners retain full access.';